FROM columns_expected e LEFT JOIN pg_attribute a ON a.attrelid=to_regclass('public.'||e.tab) AND a.attname=e.col AND NOT a.attisdropped
UNION ALL
SELECT 'FUNCTION '||e.sig,coalesce(md5(btrim(replace(p.prosrc,E'\r\n',E'\n'),E' \t\r\n'))=e.hash,false)
FROM functions_expected e LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.sig)
UNION ALL
SELECT 'TRIGGER '||e.tab||'.'||e.name,coalesce(t.tgenabled::text=e.enabled AND t.tgfoid=to_regprocedure('public.'||e.fn),false)
