 (SELECT coalesce(jsonb_agg(x ORDER BY x),'[]'::jsonb) FROM unnest(c.relacl::text[]) x))=e.expected,false)
FROM security_expected e LEFT JOIN pg_class c ON c.oid=to_regclass('public.'||e.tab)
UNION ALL
