),
expected(sig,hash,internal) AS (VALUES ('public.hotel_shared_semantic_internal(text,jsonb)','1d7053f3a7a3472d1a00278798d48cf1',true),('public.hotel_shared_chain_internal(text,jsonb,jsonb)','e444f7370b83e6e93d8f93fc6149fd30',true),('public.hotel_shared_verified_segments_internal(uuid[])','9c255110adb3e596514a2a65a6bd91d6',true),('public.get_completed_shared_hotel_stays(date)','8a1a48e8956ea5530a7a37858d08400d',false),('public.get_operation_hotel_room_projections_v2(uuid[])','02fb77fc5a08c30eaae2f1d9cce5f18f',false),('public.get_hotel_shared_room_history(date)','560ee0f917e1673026bc4d3c7e98f535',false)), function_checks AS (
SELECT e.sig,coalesce(md5(btrim(p.prosrc,E' \t\r\n'))=e.hash AND
(p.provolatile=CASE WHEN e.sig LIKE '%semantic%' OR e.sig LIKE '%chain%' THEN 'i' ELSE 's' END)
AND p.proconfig @> ARRAY['search_path=public, pg_temp']
AND (e.internal OR p.prosecdef)
AND NOT has_function_privilege('anon',p.oid,'EXECUTE')
AND has_function_privilege('authenticated',p.oid,'EXECUTE')=NOT e.internal
AND has_function_privilege('service_role',p.oid,'EXECUTE')=NOT e.internal,false) ok
FROM expected e LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.sig)
UNION ALL SELECT '004_PRESERVED',coalesce((SELECT md5(btrim(prosrc,E' \t\r\n'))='27cd8bbdd8231acab0fa631727652c0d' FROM pg_proc WHERE oid=to_regprocedure('public.get_operation_hotel_room_projections(uuid[])')),false)
),
all_checks AS (SELECT check_name,ok FROM catalog_checks UNION ALL SELECT sig,ok FROM function_checks)
SELECT check_name,CASE WHEN ok THEN 'PASS' ELSE 'STOP_REVIEW_REQUIRED' END status FROM all_checks
UNION ALL SELECT '00_OVERALL',CASE WHEN bool_and(ok) THEN 'POSTFLIGHT_PASS' ELSE 'STOP_REVIEW_REQUIRED' END FROM all_checks
ORDER BY check_name;
ROLLBACK;
